Import ListNotations.
Definition setlim (L : Z) (h : VmMaps) : VmMaps :=
  mkVmMapsFull (vm_reserved h) (vm_maps h) (vm_noaccess h) (vm_start_brk h) (vm_brk h) L (vm_mmap_base h) (vm_init_sp h).
Definition relim (L : Z) (m : Model) : Model := with_vmmaps (setlim L (m_vmmaps m)) m.
Definition map_cr (f : Model -> Model) (r : check_result) : check_result :=
  match r with CheckOk m evs => CheckOk (f m) evs | x => x end.
Create HintDb relim.
