Lemma forget_vm_ranges_relim : forall r L m,
  Sys.Mm.Mmap.forget_vm_ranges r (relim L m) = relim L (Sys.Mm.Mmap.forget_vm_ranges r m).
Proof. induction r as [|[a n] r IH]; intros L m; [reflexivity|]. cbn [Sys.Mm.Mmap.forget_vm_ranges]. rewrite <- IH. reflexivity. Qed.

