Ltac unif_arm := intros; autorewrite with arm_unfold; chkunf; autorewrite with relim; dmatch; reflexivity.
Ltac bsplit := repeat match goal with
  | H : (_ && _)%bool = true |- _ => apply Bool.andb_true_iff in H; destruct H
  | H : (_ && _)%bool = false |- _ => apply Bool.andb_false_iff in H; destruct H
  | H : negb _ = false |- _ => apply Bool.negb_false_iff in H
  | H : negb _ = true |- _ => apply Bool.negb_true_iff in H
  | H : (_ || _)%bool = true |- _ => apply Bool.orb_true_iff in H; destruct H
  | H : (_ || _)%bool = false |- _ => apply Bool.orb_false_iff in H; destruct H
  | H : bv_eqb _ _ = true |- _ => apply Fs.bv_eqb_eq in H; subst
  | H : bv_eqb ?x ?x = false |- _ => rewrite (proj2 (Fs.bv_eqb_eq x x) eq_refl) in H; discriminate H end.
Ltac zleb_contra := bsplit; try congruence; repeat match goal with
  | H : (_ <=? _)%Z = true |- _ => apply Z.leb_le in H
  | H : (_ <=? _)%Z = false |- _ => apply Z.leb_gt in H
  | H : (_ <? _)%Z = true |- _ => apply Z.ltb_lt in H
  | H : (_ <? _)%Z = false |- _ => apply Z.ltb_ge in H end; lia.
Ltac unif_fin := intros; try discriminate; try reflexivity;
  try (cbn [map_cr]; rewrite <- ?forget_vm_ranges_relim; reflexivity);
  try (cbn [map_cr]; rewrite <- ?forget_vm_ranges_relim; f_equal; f_equal; reflexivity);
  try (exfalso; zleb_contra; fail).
Ltac destr_model m := destruct m as [[?fd ?pp] [[?r ?mp ?na ?sb ?b ?lim ?mb ?isp] ?lz ?mt] [?si ?ur ?nt ?cx] [?fsi] ?proc [?lc ?lno] [?clk]].
Ltac unif_arm_b2 HB := revert HB; autorewrite with arm_unfold; chkunf; autorewrite with relim; dmatchB; unif_fin.
Ltac unif_arm_b HB := revert HB; autorewrite with arm_unfold; match goal with m : Model |- _ => destr_model m end; fullunf; dmatchB; unif_fin.
